1. package io.cucumber.junit.platform.engine;
2. 
3. import io.cucumber.core.eventbus.UuidGenerator;
4. import io.cucumber.core.feature.FeatureIdentifier;
5. import io.cucumber.core.feature.FeatureParser;
6. import io.cucumber.core.resource.ClassLoaders;
7. import io.cucumber.core.resource.ResourceScanner;
8. import io.cucumber.core.runtime.UuidGeneratorServiceLoader;
9. import io.cucumber.junit.platform.engine.CucumberDiscoverySelectors.FeatureElementSelector;
10. import io.cucumber.junit.platform.engine.CucumberDiscoverySelectors.FeatureWithLinesSelector;
11. import io.cucumber.plugin.event.Node;
12. import org.junit.platform.commons.support.Resource;
13. import org.junit.platform.engine.DiscoveryIssue;
14. import org.junit.platform.engine.DiscoverySelector;
15. import org.junit.platform.engine.TestDescriptor;
16. import org.junit.platform.engine.UniqueId;
17. import org.junit.platform.engine.discovery.ClassSelector;
18. import org.junit.platform.engine.discovery.ClasspathResourceSelector;
19. import org.junit.platform.engine.discovery.FileSelector;
20. import org.junit.platform.engine.discovery.UniqueIdSelector;
21. import org.junit.platform.engine.discovery.UriSelector;
22. import org.junit.platform.engine.support.descriptor.ClassSource;
23. import org.junit.platform.engine.support.discovery.DiscoveryIssueReporter;
24. import org.junit.platform.engine.support.discovery.SelectorResolver;
25. 
26. import java.net.URI;
27. import java.nio.file.Path;
28. import java.util.Collections;
29. import java.util.Optional;
30. import java.util.Set;
31. import java.util.function.Function;
32. import java.util.function.Predicate;
33. import java.util.function.Supplier;
34. 
35. import static io.cucumber.core.feature.FeatureIdentifier.isFeature;
36. import static io.cucumber.junit.platform.engine.CucumberDiscoverySelectors.FeatureElementSelector.selectElement;
37. import static io.cucumber.junit.platform.engine.CucumberDiscoverySelectors.FeatureElementSelector.selectElementAt;
38. import static io.cucumber.junit.platform.engine.CucumberDiscoverySelectors.FeatureElementSelector.selectElementsAt;
39. import static io.cucumber.junit.platform.engine.CucumberDiscoverySelectors.FeatureElementSelector.selectElementsOf;
40. import static java.util.Collections.singleton;
41. import static java.util.stream.Collectors.toList;
42. import static java.util.stream.Collectors.toSet;
43. import static org.junit.platform.engine.DiscoveryIssue.Severity.WARNING;
44. import static org.junit.platform.engine.discovery.DiscoverySelectors.selectPackage;
45. 
46. final class FeatureFileResolver implements SelectorResolver {
47.     private final ResourceScanner<FeatureWithSource> featureScanner;
48. 
49.     private final FeatureParserWithCaching featureParser;
50.     private final Predicate<String> packageFilter;
51.     private final DiscoveryIssueReporter issueReporter;
52.     private final CucumberTestDescriptor.Builder testDescriptorBuilder;
53. 
54.     FeatureFileResolver(
55.             CucumberConfiguration configuration, Predicate<String> packageFilter, DiscoveryIssueReporter issueReporter
56.     ) {
57.         this.packageFilter = packageFilter;
58.         this.issueReporter = issueReporter;
59.         this.featureParser = createFeatureParser(configuration, issueReporter);
60.         this.featureScanner = new ResourceScanner<>(
61.             ClassLoaders::getDefaultClassLoader,
62.             FeatureIdentifier::isFeature,
63.             featureParser::parseResource);
64.         this.testDescriptorBuilder = CucumberTestDescriptor.builder(configuration);
65.     }
66. 
67.     private static FeatureParserWithCaching createFeatureParser(
68.             CucumberConfiguration options, DiscoveryIssueReporter issueReporter
69.     ) {
70.         Supplier<ClassLoader> classLoader = FeatureFileResolver.class::getClassLoader;
71.         UuidGeneratorServiceLoader uuidGeneratorServiceLoader = new UuidGeneratorServiceLoader(classLoader, options);
72.         UuidGenerator uuidGenerator = uuidGeneratorServiceLoader.loadUuidGenerator();
73.         FeatureParser featureParser = new FeatureParser(uuidGenerator::generateId);
74.         FeatureParserWithSource featureParserWithSource = new FeatureParserWithSource(featureParser);
75.         FeatureParserWithIssueReporting featureParserWithIssueReporting = new FeatureParserWithIssueReporting(
76.             featureParserWithSource, issueReporter);
77.         return new FeatureParserWithCaching(featureParserWithIssueReporting);
78.     }
79. 
80.     @Override
81.     public Resolution resolve(DiscoverySelector selector, Context context) {
82.         if (selector instanceof FeatureElementSelector elementSelector) {
83.             return resolve(elementSelector, context);
84.         }
85.         if (selector instanceof FeatureWithLinesSelector featureWithLinesSelector) {
86.             return resolve(featureWithLinesSelector);
87.         }
88.         return SelectorResolver.super.resolve(selector, context);
89.     }
90. 
91.     public Resolution resolve(FeatureElementSelector selector, Context context) {
92.         FeatureWithSource feature = selector.getFeature();
93.         Node selected = selector.getElement();
94.         return selected.getParent()
95.                 .map(parent -> context.addToParent(() -> selectElement(feature, parent),
96.                     createTestDescriptor(feature, selected)))
97.                 .orElseGet(() -> context.addToParent(createTestDescriptor(feature, selected)))
98.                 .map(descriptor -> Match.exact(descriptor, () -> selectElementsOf(feature, selected)))
99.                 .map(Resolution::match)
100.                 .orElseGet(Resolution::unresolved);
101.     }
102. 
103.     private Function<TestDescriptor, Optional<TestDescriptor>> createTestDescriptor(
104.             FeatureWithSource feature, Node selected
105.     ) {
106.         return parent -> testDescriptorBuilder.build(parent, feature, selected);
107.     }
108. 
109.     public Resolution resolve(FeatureWithLinesSelector selector) {
110.         URI uri = selector.getUri();
111.         Set<DiscoverySelector> selectors = featureScanner
112.                 .scanForResourcesUri(uri)
113.                 .stream()
114.                 .flatMap(feature -> selectElementsAt(feature, selector::getFilePositions, issueReporter))
115.                 .collect(toSet());
116. 
117.         return toResolution(selectors);
118.     }
119. 
120.     @Override
121.     public Resolution resolve(FileSelector selector, Context context) {
122.         Path path = selector.getPath();
123.         if (!isFeature(path)) {
124.             return Resolution.unresolved();
125.         }
126. 
127.         Set<FeatureElementSelector> selectors = featureParser.parseResource(path)
128.                 .map(feature -> selectElementAt(feature, selector::getPosition, issueReporter))
129.                 .map(Collections::singleton)
130.                 .orElseGet(Collections::emptySet);
131. 
132.         return toResolution(selectors);
133.     }
134. 
135.     @SuppressWarnings("deprecation") // TODO: Updagrade
136.     @Override
137.     public Resolution resolve(ClasspathResourceSelector selector, Context context) {
138.         Set<Resource> resources = selector.getClasspathResources();
139.         if (!resources.stream().allMatch(resource -> isFeature(resource.getName()))) {
140.             return resolveClasspathResourceSelectorAsPackageSelector(selector);
141.         }
142.         if (resources.size() > 1) {
143.             throw new IllegalArgumentException("Found %s resources named %s on the classpath %s."
144.                     .formatted(
145.                         resources.size(), //
146.                         selector.getClasspathResourceName(), //
147.                         resources.stream().map(Resource::getUri).collect(toList())));
148.         }
149.         return resources.stream()
150.                 .findFirst()
151.                 .filter(resource -> isFeature(resource.getName()))
152.                 .flatMap(featureParser::parseResource)
153.                 .map(feature -> selectElementAt(feature, selector::getPosition, issueReporter))
154.                 .map(Collections::singleton)
155.                 .map(FeatureFileResolver::toResolution)
156.                 .orElseGet(Resolution::unresolved);
157.     }
158. 
159.     @SuppressWarnings("DeprecatedIsStillUsed")
160.     @Deprecated
161.     private Resolution resolveClasspathResourceSelectorAsPackageSelector(ClasspathResourceSelector selector) {
162.         Set<DiscoverySelector> selectors = featureScanner
163.                 .scanForClasspathResource(selector.getClasspathResourceName(), packageFilter)
164.                 .stream()
165.                 .map(feature -> selectElementAt(feature, selector::getPosition, issueReporter))
166.                 .collect(toSet());
167. 
168.         warnClasspathResourceSelectorUsedForPackage(selector);
169. 
170.         return toResolution(selectors);
171.     }
172. 
173.     private void warnClasspathResourceSelectorUsedForPackage(ClasspathResourceSelector selector) {
174.         String classpathResourceName = selector.getClasspathResourceName();
175.         String packageName = classpathResourceName.replaceAll("/", ".");
176.         String message = "The classpath resource selector '%s' should not be used to select features in a package. Use the package selector with '%s' instead"
177.                 .formatted(classpathResourceName, packageName);
178.         issueReporter.reportIssue(DiscoveryIssue.builder(WARNING, message));
179.     }
180. 
181.     @Override
182.     public Resolution resolve(UriSelector selector, Context context) {
183.         URI uri = selector.getUri();
184.         Set<DiscoverySelector> selectors = singleton(FeatureWithLinesSelector.from(uri));
185.         return toResolution(selectors);
186.     }
187. 
188.     @SuppressWarnings("deprecation")
189.     @Override
190.     public Resolution resolve(ClassSelector selector, Context context) {
191.         Class<?> javaClass = selector.getJavaClass();
192.         Cucumber annotation = javaClass.getAnnotation(Cucumber.class);
193.         if (annotation != null) {
194.             warnAboutDeprecatedCucumberClass(javaClass);
195.             String packageName = javaClass.getPackage().getName();
196.             Set<DiscoverySelector> selectors = singleton(selectPackage(packageName));
197.             return toResolution(selectors);
198.         }
199.         return Resolution.unresolved();
200.     }
201. 
202.     private void warnAboutDeprecatedCucumberClass(Class<?> javaClass) {
203.         String message = "The @Cucumber annotation has been deprecated. See the Javadoc for more details.";
204.         DiscoveryIssue issue = DiscoveryIssue.builder(WARNING, message)
205.                 .source(ClassSource.from(javaClass))
206.                 .build();
207.         issueReporter.reportIssue(issue);
208.     }
209. 
210.     @Override
211.     public Resolution resolve(UniqueIdSelector selector, Context context) {
212.         UniqueId uniqueId = selector.getUniqueId();
213.         Set<FeatureWithLinesSelector> selectors = FeatureWithLinesSelector.from(uniqueId);
214.         return toResolution(selectors);
215.     }
216. 
217.     private static Resolution toResolution(Set<? extends DiscoverySelector> selectors) {
218.         if (selectors.isEmpty()) {
